from functools import singledispatch

@singledispatch
def describe(x):
    return f"object: {x!r}"

@describe.register
def _(x: int):
    return f"int with {x.bit_length()} bits"

@describe.register
def _(x: str):
    return f"text of {len(x)} chars"

print(describe("hello"))
print(describe(255))
print(describe(2.5))

