from functools import singledispatch

@singledispatch
def size_of(x):
    return 1

@size_of.register
def _(x: list):
    return sum(size_of(item) for item in x)

@size_of.register
def _(x: dict):
    return sum(size_of(v) for v in x.values())

data = {"a": [1, 2, [3, 4]], "b": {"c": 5}, "d": "txt"}
print(size_of(data))
print(sorted(t.__name__ for t in size_of.registry))
print(size_of.dispatch(bool).__name__)
